import {producersOf,vocalistsOf,comparePeople} from './people.js';
export const MAX_GUESSES=10;
export function normalize(text){return String(text??'').normalize('NFKD').replace(/(?<=\p{Script=Latin})\p{M}+/gu,'').normalize('NFKC').toLocaleLowerCase().replace(/[\s\p{P}\p{S}]/gu,'');}
export function compareNumber(guess,answer,tolerance){return{status:guess===answer?'exact':Math.abs(guess-answer)<=tolerance?'close':'wrong',direction:answer>guess?'up':answer<guess?'down':null};}
export function compareSingers(guess,answer){const a=new Set(guess),b=new Set(answer);return a.size===b.size&&[...a].every(v=>b.has(v))?'exact':[...a].some(v=>b.has(v))?'close':'wrong';}
export function compareMetric(guess,answer,{tolerance=0,relative=0,rank=false}={}){if(!Number.isFinite(guess)||!Number.isFinite(answer))return{status:'unknown',direction:null};const result=compareNumber(guess,answer,Math.max(tolerance,Math.max(guess,answer)*relative));if(rank&&result.direction)result.direction=result.direction==='up'?'down':'up';return result;}
export const VIEW_TOLERANCE=1_000_000;
export function compareViews(guess,answer){if(!['ok','stale'].includes(guess?.status)||!['ok','stale'].includes(answer?.status))return{status:'unknown',direction:null};if(guess.snapshotAt&&answer.snapshotAt&&guess.snapshotAt!==answer.snapshotAt)return{status:'unknown',direction:null};return compareMetric(guess.count,answer.count,{tolerance:VIEW_TOLERANCE});}
export function compareChart(guess,answer,key){if(guess?.status!=='complete'||answer?.status!=='complete')return{status:'unknown',direction:null};if(key==='peak'&&(guess.peak===null||answer.peak===null))return{status:guess.weeks===0&&answer.weeks===0?'exact':'wrong',direction:null};return compareMetric(guess[key],answer[key],{tolerance:2,rank:key==='peak'});}
export function evaluate(guess,answer,guessViews={},answerViews={}){const producers=comparePeople(producersOf(guess),producersOf(answer)),singers=comparePeople(vocalistsOf(guess),vocalistsOf(answer));return{song:guess.id===answer.id?'exact':'wrong',producer:producers.status,singers:singers.status,producerDetails:producers,singerDetails:singers,year:compareNumber(guess.year,answer.year,2),views:Object.fromEntries(['niconico','youtube'].map(key=>[key,compareViews(guessViews[key],answerViews[key])])),billboard:{weeks:compareChart(guess.rankings?.billboard,answer.rankings?.billboard,'weeks'),peak:compareChart(guess.rankings?.billboard,answer.rankings?.billboard,'peak')},weekly:{weeks:compareChart(guess.rankings?.weekly,answer.rankings?.weekly,'weeks'),peak:compareChart(guess.rankings?.weekly,answer.rankings?.weekly,'peak')}};}
export function getBeijingDate(now=new Date()){const parts=new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(now);return['year','month','day'].map(type=>parts.find(part=>part.type===type).value).join('-');}
export function dailyIndex(date,version,count){let hash=2166136261;for(const char of version+'|'+date){hash^=char.charCodeAt(0);hash=Math.imul(hash,16777619)}return(hash>>>0)%count;}
export function formatDuration(seconds){return Math.floor(seconds/60)+':'+String(seconds%60).padStart(2,'0');}
export function gameStatus(guesses,answerId){return guesses.includes(answerId)?'won':guesses.length>=MAX_GUESSES?'lost':'playing';}
const searchIndexes=new WeakMap();
const phonetic=text=>normalize(text).replace(/sy([auo])/g,'sh$1').replace(/ty([auo])/g,'ch$1').replace(/zy([auo])/g,'j$1').replace(/si/g,'shi').replace(/ti/g,'chi').replace(/tu/g,'tsu').replace(/([^aeiou])ou/g,'$1o').replace(/([aeiou])\1/g,'$1');
function editDistance(a,b,max){if(Math.abs(a.length-b.length)>max)return max+1;let prev=Array.from({length:b.length+1},(_,i)=>i);for(let i=1;i<=a.length;i++){const row=[i];let min=i;for(let j=1;j<=b.length;j++){row[j]=Math.min(row[j-1]+1,prev[j]+1,prev[j-1]+Number(a[i-1]!==b[j-1]));min=Math.min(min,row[j]);}if(min>max)return max+1;prev=row;}return prev[b.length];}
function searchIndex(songs){if(searchIndexes.has(songs))return searchIndexes.get(songs);const rows=songs.map(song=>({song,terms:[{text:song.title,kind:'title'},...(song.aliases||[]).map(text=>({text,kind:'alias'})),...producersOf(song).flatMap(p=>[p.name,...(p.aliases||[]),...(p.searchAliases||[])].map(text=>({text,kind:'producer'}))),...(song.producerSearchAliases||[]).map(text=>({text,kind:'producer'})),...vocalistsOf(song).flatMap(p=>[p.name,...(p.aliases||[])].map(text=>({text,kind:'singer'})))].filter(t=>typeof t.text==='string'&&t.text.trim()).map(t=>({...t,key:normalize(t.text),phonetic:phonetic(t.text)}))}));searchIndexes.set(songs,rows);return rows;}
export function searchSongMatches(songs,query,excluded=[]){const q=normalize(String(query??'').slice(0,160)),pq=phonetic(q),cq=q.length>=4&&/[\u4e00-\u9fff]/.test(q)&&!/[\u3040-\u30ff]/.test(q)?q.replace(/的/g,''):null,excludedSet=new Set(excluded),index=searchIndex(songs),matches=[];for(const {song,terms}of index){if(excludedSet.has(song.id))continue;if(!q){matches.push({song,score:30,matchedAlias:null,matchType:'browse'});continue;}let best=null;for(const t of terms){let score=99,type='';const p=t.kind==='producer'?6:t.kind==='singer'?8:0;if(t.key===q){score=p;type='exact';}else if(t.key.startsWith(q)){score=10+p;type='prefix';}else if(t.key.includes(q)){score=20+p;type='partial';}else if(cq&&!/[\u3040-\u30ff]/.test(t.key)&&t.key.replace(/的/g,'').includes(cq)){score=25+p;type='name_variant';}else if(/^[a-z]+$/.test(q)&&q.length>=4&&t.phonetic.includes(pq)){score=25+p;type='romanization';}if(score<99&&(!best||score<best.score))best={song,score,matchedAlias:t.text,matchKind:t.kind,matchType:type};}if(best)matches.push(best);}
 if(!matches.length&&/^[a-z]+$/.test(q)&&q.length>=5){const max=q.length>=10?2:1;for(const {song,terms}of index){if(excludedSet.has(song.id))continue;const candidate=terms.filter(t=>['title','alias'].includes(t.kind)&&/^[a-z]+$/.test(t.key)&&t.key.length<=80).map(t=>({...t,distance:editDistance(q,t.key,max)})).sort((a,b)=>a.distance-b.distance)[0];if(candidate&&candidate.distance<=max)matches.push({song,score:40+candidate.distance,matchedAlias:candidate.text,matchKind:candidate.kind,matchType:'suggested'});}}
 return matches.sort((a,b)=>a.score-b.score||a.song.title.localeCompare(b.song.title,'ja')||a.song.id.localeCompare(b.song.id));}
export function searchSongs(songs,query,excluded=[]){return searchSongMatches(songs,query,excluded).map(result=>result.song);}
export function validateLibrary(library){if(!library||typeof library.version!=='string'||!Array.isArray(library.songs)||!library.songs.length)throw new Error('曲库格式有误');const ids=new Set();for(const s of library.songs){if(typeof s.id!=='string'||ids.has(s.id)||typeof s.title!=='string'||!s.title.replace(/[\s\p{Cf}]/gu,'')||typeof s.producerId!=='string'||typeof s.producer!=='string'||!Array.isArray(s.singers)||!s.singers.length||!Array.isArray(s.aliases)||!Array.isArray(s.producerAliases)||!Number.isInteger(s.year)||!Number.isInteger(s.duration)||s.duration<=0)throw new Error('歌曲资料有误');for(const people of [s.producers,s.vocalists])if(people!==undefined&&(!Array.isArray(people)||!people.length||new Set(people.map(p=>p?.id)).size!==people.length||people.some(p=>!p||typeof p.id!=='string'||!p.id||typeof p.name!=='string'||!p.name||!Array.isArray(p.aliases)||p.aliases.some(a=>typeof a!=='string'))))throw new Error('作者或歌姬标签资料有误');ids.add(s.id)}return library;}
export function restoreGame(saved,songs,fallbackAnswerId){const ids=new Set(songs.map(s=>s.id));if(!saved||!ids.has(saved.answerId)||!Array.isArray(saved.guesses)||saved.guesses.length>MAX_GUESSES||saved.guesses.some(id=>!ids.has(id))||new Set(saved.guesses).size!==saved.guesses.length)return{answerId:fallbackAnswerId,guesses:[]};const win=saved.guesses.indexOf(saved.answerId);if(win!==-1&&win!==saved.guesses.length-1)return{answerId:fallbackAnswerId,guesses:[]};return{answerId:saved.answerId,guesses:[...saved.guesses]};}
